[ExtensionOf(formStr(EssLeaveRequestCalendar))]
internal final class NVEssLeaveRequestCalendar_Extension
{
    private HcmWorker locCallerWorker;


}

Method.Source:
public void init()
{
    next init();

    if (this.args().record() is HcmWorker)
    {
        locCallerWorker = this.args().record() as HcmWorker;
    }
    else if (this.args().record() is DirPartyTable)
    {
        DirPartyTable locDirPartyTable = this.args().record() as DirPartyTable;
        locCallerWorker = HcmWorker::findByPerson(locDirPartyTable.RecId);
    }
}

public void run()
{
    next run();

    this.initBalanceDetails();
}

public void initBalanceDetails()
{
    date locAsOfDate = AsOfDate.dateValue() == dateNull()? DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()): AsOfDate.dateValue();
    NVLeaveBalanceDetailsTmp detailsTmp = NVLeaveBalanceDetailsTmp::balanceByLeaveType(locCallerWorker.RecId, locAsOfDate);

    NVLeaveBalanceDetailsTmp.setTmpData(detailsTmp);
    NVLeaveBalanceDetailsTmp_ds.executeQuery();
    NVLeaveBalanceDetailsTmp_ds.research(true);
}

[
    FormControlEventHandler(formControlStr(EssLeaveRequestCalendar, Balances), FormControlEventType::PageActivated),
    FormControlEventHandler(formControlStr(EssLeaveRequestCalendar, Apply), FormControlEventType::Clicked)
]
public static void Balances_Update(FormControl sender, FormControlEventArgs e)
{
    FormRun formRun = sender.formRun();

    formRun.initBalanceDetails();
}
